def restore_expression(input_string):
    n = len(input_string)
    for i in range(1, n - 1):
        for j in range(i + 1, n):
            a = input_string[:i]
            b = input_string[i:j]
            c = input_string[j:]
            if a[0] != '0' and b[0] != '0' and c[0] != '0':
                if int(a) + int(b) == int(c):
                    return f"{a}+{b}={c}"
    return None

# Read input from stdin
input_string = input().strip()

# Restore and print the expression
output_string = restore_expression(input_string)
print(output_string)
